import { HistFormat, HistResultType, PrismaClient } from '../index.js';

export interface StatsContext {
  prisma: PrismaClient;
  redis?: any;
  statsVersion?: number;
  format?: HistFormat;
  gender?: string; // 'male' | 'female'
}

// 1. Team Form
export interface MatchFormSummary {
  matchId: string;
  cricsheetMatchId: string;
  date: string;
  vsTeam: {
    id: string;
    name: string;
    code: string;
  };
  result: 'W' | 'L' | 'T' | 'NR';
  marginText: string | null;
  teamRuns: number | null;
  opponentRuns: number | null;
}

export interface TeamFormResult {
  teamId: string;
  matches: MatchFormSummary[];
}

// 2. Head to Head
export interface H2HRecentMatch {
  matchId: string;
  cricsheetMatchId: string;
  date: string;
  format: string;
  winnerId: string | null;
  winnerName: string | null;
  marginText: string | null;
  teamAScore: string | null;
  teamBScore: string | null;
}

export interface HeadToHeadResult {
  totalMatches: number;
  teamAWins: number;
  teamBWins: number;
  ties: number;
  noResults: number;
  recentMatches: H2HRecentMatch[];
}

// 3. Team Comparison
export interface SingleTeamMetrics {
  teamId: string;
  teamName: string;
  matchesCount: number;
  winCount: number;
  winPercentage: number | null;
  avgScoreBattingFirst: number | null;
  avgScoreBattingSecond: number | null;
  highestScore: number | null;
  lowestScore: number | null;
}

export interface TeamComparisonResult {
  sampleSizeA: number;
  sampleSizeB: number;
  teamA: SingleTeamMetrics;
  teamB: SingleTeamMetrics;
  venueComparison: {
    venueId: string;
    teamA: SingleTeamMetrics;
    teamB: SingleTeamMetrics;
  } | null;
}

// 4. Venue Stats
export interface VenueStatsResult {
  venueId: string;
  venueName: string;
  totalMatches: number;
  wonBattingFirst: number;
  wonBattingSecond: number;
  winPctBattingFirst: number;
  winPctBattingSecond: number;
  ties: number;
  noResults: number;
  avgFirstInningsScore: number | null;
  avgSecondInningsScore: number | null;
  highestScoreChased: number | null;
  lowestScoreDefended: number | null;
  tossImpactWinPct: number | null;
}

// 5. Pace vs Spin
export interface PaceSpinAvailableResult {
  available: true;
  totalWickets: number;
  paceWickets: number;
  spinWickets: number;
  paceWicketPct: number;
  spinWicketPct: number;
  paceEconomy: number | null;
  spinEconomy: number | null;
  paceAverage: number | null;
  spinAverage: number | null;
  unclassifiedWickets: number;
}

export interface PaceSpinUnavailableResult {
  available: false;
  reason: 'insufficient_bowler_classification' | 'no_wickets_recorded';
  unclassifiedPct?: number;
}

export type PaceSpinResult = PaceSpinAvailableResult | PaceSpinUnavailableResult;

// 6. Recent At Venue
export interface RecentMatchSummary {
  matchId: string;
  cricsheetMatchId: string;
  date: string;
  format: string;
  teamA: { id: string; name: string; code: string; score: string | null };
  teamB: { id: string; name: string; code: string; score: string | null };
  winnerName: string | null;
  marginText: string | null;
}

export interface RecentAtVenueResult {
  venueId: string;
  matches: RecentMatchSummary[];
}
